mapper.insert:
begin
update tl_admin.yj_data_score t set t.score=0 where t.nsrdzdah=#{nsrdzdah};
update tl_admin.yj_data_yjxx y  set y.cl_flag='1' , y.cl_date=sysdate ,y.cl_user=#{clr}
where y.nsrdzdah=#{nsrdzdah}
    and y.swflag='1' and y.cl_flag='0';
COMMIT;
end;

mapper.select:
select t.sbym, h.sbywb_dm as sbywbDm, h.sssq, h.sbpc, t.yjcode, y.yjname as yjcodeZh, t.zbcode, y.zbname as zbcodeZh, t.yj_msg as yjMsg, t.yj_object as yjObject, t.yj_count as yjCount, t.yj_amt as yjAmt, t.yj_tax as yjTax, t.yj_record as yjRecord, t.score, t.cl_flag as clFlag, t.cl_date as clDate, t.cl_user as clUser, t.cl_msg as clMsg, t.bmdflag, t.bz from tl_admin.yj_data_yjxx t, tl_bjts.sb_sbxx_hz h, tl_bjts.gs_dj_cktmsdab c, tl_admin.yj_dic_yjzb y where t.sbid = h.id(+) and t.nsrdzdah = h.nsrdzdah(+) and t.nsrdzdah = c.nsrdzdah and c.nsrsbh = #{nsrsbh} and t.yjcode = y.yjcode and t.zbcode = y.zbcode and t.swflag='1'
and t.yjcode=#{yjcode}
and t.zbcode=#{zbcode}
and t.cl_flag=#{clFlag}
and t.yj_object like '%'||#{yjObject}||'%'
and t.bz like '%'||#{bz}||'%'
and t.yj_amt <=#{yjAmtEnd}
and t.yj_amt >=#{yjAmtStart}

select t.syqy,t.zbcode,t.zbname,decode(t.jslx ,1 , '按报关单', 2, '按批次汇总', 3, '六个月汇总', t.jslx) as jslx, t.p1name, nvl(s.p1val,t.p1val) as p1valchange, t.p2name, nvl(s.p2val,t.p2val) as p2valchange, t.p3name, nvl(s.p3val,t.p3val) as p3valchange, t.p4name, nvl(s.p4val,t.p4val) as p4valchange, nvl(s.score,t.score) as score, decode(s.yxbz, null, 'Y', s.yxbz) as yxbz, s.swjgdm, swjg.swjg_jc as swjgmc from tl_admin.yj_dic_yjzbswjg s left join tl_admin.yj_dic_yjzb t on (t.zbcode = s.zbcode
and s.swjgdm like substr(#{swjgdm},1,5)||'%'
and (s.swjgdm = substr(#{swjgdm},1,5)||'000000' or s.swjgdm = #{swjgdm})
) left join tl_admin.dm_swjg swjg on (s.swjgdm = swjg.swjg_dm) where t.yjcode = #{yjcode} and t.sysw='1'
and s.zbcode = #{zbcode}
order by s.zbcode

select s.qyhgdm,s.shxyno,s.nsrmc,t.yjcode,c.yjname,t.id ,t.id as bmdid,c.yjobject, decode(t.objflag,0 , '整体放行', 1, '按预警对象放行', t.objflag) as objflag, t.objflag as objflagBz, t.yxbz,t.swjgdm,t.yyms,d.swjg_jc as swjgmc from tl_admin.yj_cs_bmd t,tl_bjts.gs_dj_cktmsdab s ,tl_admin.yj_dic_code c,tl_bjts.dm_swjg d where t.nsrdzdah=s.nsrdzdah and c.yjcode=t.yjcode and d.swjg_dm=t.swjgdm and t.swjgdm like #{qxdm}||'%' and c.yxbz='Y'
and t.swjgdm like #{tsjg}||'%'
and (s.qyhgdm like '%'||#{qybs}||'%' or s.shxyno like '%'||#{qybs}||'%')
and s.nsrmc like '%'||#{qymc}||'%'
and t.objflag =#{objflag}
and t.yjcode =#{yjcode}

select zbcode,zbname
from tl_admin.yj_dic_yjzb
where yjcode = #{yjcode}

SELECT tmp.*, s.FXDJ_MC as fxdjMc,f.FXDJ_MC as fxdjDz
FROM (
SELECT m.YSFS_DM as ysfsDm,ysfs.dname as ysfsMc,
m.SPDL_DM as spdlDm,
sp.cksp_mc as spdlMc,
m.QYCODE_HYD as qycodeHyd,
m.QYCODE_HG as qycodeHg,
m.QYCODE_MDG as qycodeMdg,
dmhyd.qyname as qynameHyd,
dmhg.qyname as qynameHg,
dmmdg.gb_name as qynameMdg,
m.QYHS_ALL as qyhsAll,
m.QYZB_ALL as qyzbAll,
m.BGDFS_ALL as bgdfsAll,
m.BGDZB_ALL as bgdzbAll,
m.MYLAJ_ALL as mylajAll,
m.MYZB_ALL as myzbAll,
m.QYHS_SX as qyhsSx,
m.QYZB_SX as qyzbSx,
m.BGDFS_SX as bgdfsSx,
m.BGDZB_SX as bgdzbSx,
m.MYLAJ_SX as mylajSx,
m.MYZB_SX as myzbSx,
m.FXDJ_ZHFXZS as fxdjZhfxzs,
m.FXDJ_DM as fxdjDm,
t.FXDJ_TZ as fxdjDzDm,
t.FXDJ_TZYY as fxdjDzYy
FROM TL_TSSH.CKLLFX_CS_WMQYLSLL m
LEFT JOIN tl_admin.sys_dict ysfs ON ysfs.dcode = m.YSFS_DM AND ysfs.dtype = 'ysfs'
LEFT JOIN tl_tssh.jcfx_dm_cksptree sp ON sp.cksp_dm = m.SPDL_DM
left join tl_admin.dm_xzqh dmhyd on dmhyd.dm = m.QYCODE_HYD
left join tl_admin.dm_xzqh dmhg on dmhg.dm = m.QYCODE_HG
left join tl_admin.dm_gbcode dmmdg on dmmdg.gb_code =  m.QYCODE_MDG
LEFT JOIN TL_TSSH.CKLLFX_CS_SWJGYJTZ t ON t.YSFS_DM = m.YSFS_DM
AND t.SPDL_DM = m.SPDL_DM
AND t.QYCODE_HYD = m.QYCODE_HYD
AND t.QYCODE_HG = m.QYCODE_HG
AND t.QYCODE_MDG = m.QYCODE_MDG
AND t.SWJG_DM = #{swjgdm}
AND t.TSJSFF_DM = '2'


        AND m.YSFS_DM LIKE '%' || #{ysfsDm} || '%'


        AND REGEXP_LIKE(m.SPDL_DM, '^(' || REPLACE(#{spdlDm}, ',', '|') || ')$')


        AND m.QYCODE_HYD = #{qycodeHyd}


        AND m.QYCODE_HG = #{qycodeHg}


        AND m.QYCODE_MDG = #{qycodeMdg}


        AND m.QYZB_ALL <= #{qyzbUpper}


        AND m.QYZB_ALL >= #{qyzbLower}


        AND m.BGDZB_ALL <= #{bgdfsUpper}


        AND m.BGDZB_ALL >= #{bgdfsLower}


        AND m.MYZB_ALL <= #{mylajUpper}


        AND m.MYZB_ALL >= #{mylajLower}


        AND m.QYZB_SX <= #{qyzbSxUpper}


        AND m.QYZB_SX >= #{qyzbSxLower}


        AND m.BGDZB_SX <= #{bgdzbSxUpper}


        AND m.BGDZB_SX >= #{bgdzbSxLower}


        AND m.MYZB_SX <= #{myzbSxUpper}


        AND m.MYZB_SX >= #{myzbSxLower}



) tmp
LEFT JOIN TL_TSSH.CKLLFX_CS_FXDJSZ f ON f.FXDJ_DM = tmp.fxdjDzDm
LEFT JOIN TL_TSSH.CKLLFX_CS_FXDJSZ s ON s.FXDJ_DM = tmp.fxdjDm


        AND s.FXDJ_DM = #{fxdjDm} or s.FXDJ_MC=#{fxdjDm}


        AND f.FXDJ_DM = #{fxdjDz}  or f.FXDJ_MC=#{fxdjDz}

SELECT dj.swjgdm,bg.djxh, dj.nsrmc AS nsrmc, NVL(dj.shxyno, dj.nsrdjno) AS nsrsbh, bg.BGDHGBH AS bgdhgbh, bg.DLZMH AS dlzmh, bg.TMSJSFF_DM AS tmsjsffDm, bg.CKRQ_1 AS ckrq, bg.MYLAJ AS mylaj, bg.YSFS_DM AS ysfsDm, bg.YSFS_DM||'-'||ysfs.dname AS ysfsMc, bg.HZDWDQ_DM AS hzdwdqDm, bg.HZDWDQ_DM||'-'||hyd.hghyd_mc AS hzdwdqMc, bg.HGGQKA_DM AS hggqkaDm, bg.HGGQKA_DM||'-'||hg.hgmc AS hggqkaMc, bg.ZZMDGDQSZ_DM AS zzmdgdqszDm, bg.ZZMDGDQSZ_DM||'-'||gb.gb_name AS zzmdgdqszMc, bg.SPDL_DM||'-'||sp.cksp_mc AS spdlDm, bg.FHMS_DM AS fhmsDm, decode(bg.FHMS_DM, '1', '整柜', '2', '散货(拼箱)','0', '散货(拼箱)', bg.FHMS_DM) AS fhmsMc, bg.JZXH AS jzxh, bg.JHPZH AS jhpzh, bg.GHFNSRSBH_1 AS ghfnsrsbh, bg.GHFNSRMC AS ghfnsrmc, bg.GHFNSRSwjg AS ghfnsrswjg, hyd.qyname AS qycodeHyd, hg.qyname AS qycodeHg, gb.QYNAME AS qycodeMdg, bg.FXDJ_ZHFXZS AS fxdjZhfxzs, bg.FXDJ_DM AS fxdjDm, fx.fxdj_mc AS fxdjMc, bg.FXDJ_GXRQ AS fxdjGxrq, fxtz.fxdj_mc AS fxdjTz, bg.FZDJ_TZYY AS fzdjTzYY, bg.WLXXLY_DM AS wlxxlyDm, decode(bg.WLXXLY_DM, '1', '出口发票', '2', '申报表', '3', '核查报送', bg.WLXXLY_DM) AS wlxxlyMc, bg.CKFPH AS ckfph, bg.CPH AS cph, bg.CPYS_CODE AS cpysCode, bg.CPYS_NAME AS cpysName, bg.QYRQ AS qyrq, bg.QYD AS qyd, bg.TYDH AS tydh, bg.QYD_XZQH AS qydXzqh, bg.TDLX_DM AS tdlxDm, decode(NVL(bg.GJEWMZT_DM,0), '0', '未生成', '1', '已生成', bg.GJEWMZT_DM) AS gjemwztdm, bg.BZ AS bz, bg.SJGXSJ AS sjgxsj FROM tl_tssh.glxt_bb_shxt_djxx dj INNER JOIN TL_TSSH.CKLLFX_DATA_BGDWL bg ON dj.djxh_js = bg.djxh LEFT JOIN tl_admin.sys_dict ysfs ON ysfs.dcode = bg.YSFS_DM AND ysfs.dtype = 'ysfs' LEFT JOIN ( SELECT hy.hghyd_dm, hy.hghyd_mc, xzqh.qyname FROM tl_admin.DM_HGHYD hy LEFT JOIN tl_admin.DM_XZQH xzqh ON hy.xzqh_dm = xzqh.dm ) hyd ON hyd.hghyd_dm = bg.HZDWDQ_DM LEFT JOIN ( SELECT h.hgcode, h.hgmc, xzqh.qyname FROM tl_admin.DM_HGCODE h LEFT JOIN tl_admin.DM_XZQH xzqh ON h.xzqh_dm = xzqh.dm ) hg ON hg.hgcode = bg.hggqka_dm LEFT JOIN tl_admin.DM_GBCODE gb ON gb.gb_code = bg.ZZMDGDQSZ_DM LEFT JOIN TL_TSSH.CKLLFX_CS_FXDJSZ fx ON fx.fxdj_dm = bg.FXDJ_DM LEFT JOIN TL_TSSH.CKLLFX_CS_FXDJSZ fxtz ON fxtz.fxdj_dm = bg.FXDJ_TZ LEFT JOIN TL_TSSH.jcfx_dm_cksptree sp ON sp.cksp_dm = bg.SPDL_DM WHERE 1=1
AND dj.swjgdm LIKE #{swjgDm} || '%'
AND bg.FXDJ_GXRQ >= #{fxdjGxrqQ}
AND bg.FXDJ_GXRQ < #{fxdjGxrqZ}+1
AND (bg.FXDJ_DM = #{fxdjDm} or fx.fxdj_mc=#{fxdjDm})
AND bg.FHMS_DM = '1'
AND bg.FHMS_DM IN ('0', '2')
AND bg.YSFS_DM = #{ysfsDm}
AND bg.TMSJSFF_DM = #{tmsjsffDm}
AND (dj.nsrmc LIKE '%' || #{qybs} || '%' OR NVL(dj.shxyno, dj.nsrdjno) LIKE '%' || #{qybs} || '%')
AND (bg.GHFNSRMC LIKE '%' || #{gybs} || '%' OR bg.GHFNSRSBH_1 LIKE '%' || #{gybs} || '%')
AND bg.BGDHGBH LIKE '%' || #{bgdhgbh}
AND bg.BGDHGBH = #{bgdhgbh}
AND bg.CKRQ_1 >= #{ckrqQ}
AND bg.CKRQ_1 <= #{ckrqZ}
AND bg.JZXH LIKE '%' || #{jzxh} || '%'
AND bg.CPH LIKE '%' || #{cph} || '%'
AND bg.CKFPH LIKE '%' || #{ckfph}
ORDER BY bg.CKRQ_1 DESC

SELECT COUNT(1)
FROM tl_tssh.glxt_bb_shxt_djxx dj
INNER JOIN TL_TSSH.CKLLFX_DATA_BGDWL bg ON dj.djxh_js = bg.djxh
WHERE bg.DJXH = #{djxh}
  AND bg.BGDHGBH = #{bgdhgbh}


        AND dj.swjgdm LIKE #{qxSwjgDm} || '%'
